function labelToNumber(label: string): number {
  let result = 0, place = 1;
  for (let i = label.length - 1; i >= 0; i--) {
    result += (label.charCodeAt(i) - 64) * place; // 'A' is code 65
    place *= 26;
  }
  return result;
}

